INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 1, 'Ben-Zayb', 'Doña Victorina:\nThis river is unbearable! The steamer moves like a sick animal.\n\nBen-Zayb:\nPerhaps the Pasig requires a brilliant solution. Señor Simoun, surely a man of your experience has an idea?', 'The remedy is simple. Cut a straight canal, close the old river, and remove whatever blocks progress.', 'The river must be improved, but only with patience and fairness.', 'The river is not the sickness. The sickness is the system ruling this country.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The River Problem');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 2, 'Don Custodio', 'Don Custodio:\nBut Señor Simoun, such a canal would cost a fortune. Towns may be destroyed.', 'Then destroy them. Progress does not wait for weak hearts.', 'Then perhaps the plan should be changed to protect the towns.', 'One day, those towns will learn that the powerful only see them as obstacles.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Cost of Progress');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 3, 'Don Custodio', 'Don Custodio:\nAnd who would pay the workers for such a project?', 'Do not pay them. Use prisoners. If there are not enough, force the townspeople to work for the State.', 'They should be paid properly. Labor without pay breeds resentment.', 'Let the people feel the cruelty clearly. Pain teaches them who their enemies are.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Forced Labor');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 4, 'Padre Salvi', 'Padre Salvi:\nSuch measures may cause unrest. The people may rebel.', 'Rebel? These people will not rise as long as authority remains strong.', 'Perhaps unrest is natural when people suffer too much.', 'Rebellion only sleeps, Padre. A single spark may wake it.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Fear of Rebellion');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 5, 'Basilio', 'Simoun descends to the lower deck and sees Basilio with Isagani.\n\nSimoun:\nDon Basilio, you are going home for vacation?\n\nBasilio:\nYes, Señor Simoun.\n\nSimoun:\nAnd this young man?\n\nBasilio:\nThis is Isagani.\n\nSimoun looks at Isagani carefully.', 'I have heard of your province. Poor, they say. A place that does not buy jewels.', 'I have heard your province is proud, even if it has little wealth.', 'Poor provinces are made poor because power steals from them.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Meeting Basilio and Isagani');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (1, 6, 'Isagani', 'Simoun:\nCome. Drink beer with me.\n\nBasilio:\nThank you, Señor, but we must decline.\n\nSimoun:\nYou do wrong. Beer gives strength. Perhaps this country lacks energy because its people drink too much water.\n\nIsagani:\nWater may seem mild, but it can become steam, ocean, and destruction.', 'A clever answer. But tell me, young man, when will your water become steam?', 'You speak with courage. Perhaps the youth still has strength after all.', 'Soon, perhaps. When the fire beneath this country becomes hot enough.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Water and Beer Exchange');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 1, 'Ben-Zayb', 'Don Custodio:\nSeñor Simoun, where have you been hiding? You missed the finest part of the journey.\n\nCaptain:\nThe river has many stories, señor. Some places here are remembered because of old legends.\n\nBen-Zayb:\nLegends? That may interest our jeweler. Señor Simoun, do such things amuse you?', 'I have seen many rivers and many landscapes. Only those with legends still interest me.', 'A river is only water. I have no patience for old stories.', 'Legends matter because they hide the crimes of those who rule.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Legend Question');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 2, 'Ben-Zayb', 'Captain:\nThere is also the cave of Doña Geronima. Padre Florentino can tell it better than I can.\n\nPadre Florentino:\nIt is an old story of a woman who waited, suffered, and was hidden away. Time turned her sorrow into legend.\n\nBen-Zayb:\nA tragic tale. Señor Simoun, what do you think of it?', 'A curious tale. People often decorate misery until it sounds like poetry.', 'Poor woman. Those with power should have protected her.', 'Powerful men bury women, truth, and nations in caves.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Doña Geronima’s Cave');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 3, 'Ben-Zayb', 'Ben-Zayb:\nCaptain, do you know where that man died? What was his name? Guevara? Navarra? Ibarra?\n\nCaptain:\nIbarra was chased near the lake. They say he jumped from the boat, swam through bullets, and disappeared. That happened thirteen years ago.\n\nPadre Sibyla:\nA fitting end for a filibuster.\n\nBen-Zayb:\nBut Señor Simoun, you are silent. Are you seasick in this little lake?', 'Seasick? No. I am merely tired of stories about dead filibusters.', 'It is a cruel story, even for a man accused of rebellion.', 'Dead? You speak too surely of a man whose body was never found.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Name of Ibarra');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 4, 'Passenger', 'Passenger:\nHave you heard of Cabesang Tales? He cleared wild land with his own hands. But when the land became useful, the friars claimed it and raised the rent.\n\nDon Custodio:\nA tenant must obey the lawful owners.\n\nPassenger:\nThe rent kept rising. When it reached two hundred pesos, Tales refused to pay.', 'If he cannot pay, give the land to someone who can. Sentiment is poor currency.', 'A man who cleared the land deserves mercy.', 'When justice is denied, a man may take back his land with blood.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Rumors of Cabesang Tales');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 5, 'Don Custodio', 'Passenger:\nCabesang Tales asked the friars to show proof that the land was truly theirs.\n\nPadre Salvi:\nQuestioning authority is dangerous.\n\nDon Custodio:\nSuch men invite trouble upon themselves.', 'Dangerous indeed. A man without power should not test those above him.', 'Perhaps asking for proof is not rebellion.', 'The day peasants ask for proof, the whole rotten order begins to fall.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Demand for Proof');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (2, 6, 'Padre Salvi', 'Passenger:\nThey say Cabesang Tales was captured by tulisanes while guarding his fields. His daughter Juli and old Tandang Selo must now find money for his ransom.\n\nBen-Zayb:\nDisorder in the provinces again. That could make a fine article.\n\nPadre Salvi:\nThe people must learn obedience, or chaos will spread.', 'Then write that weakness invites ruin. Fear keeps the countryside obedient.', 'Write that poverty drives people into despair.', 'Write that every injustice creates another outlaw.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Tales Is Captured');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 1, 'Curate', 'Inside Capitan Basilio’s house, food is being prepared for the Christmas feast. Simoun sits confidently with his jewels while the curate, the alferez, and Capitan Basilio speak with him.\n\nCapitan Basilio:\nIt is understood, Señor Simoun. We will go to Tiani to see your jewels.\n\nAlferez:\nI would also go, but I am busy. I need a watch-chain.\n\nCurate:\nAnd I need earrings. First class, of course.', 'Then you shall see only the finest. Men of position deserve jewels that show their power.', 'Perhaps jewels matter little tonight. The town outside looks poorer than before.', 'Gold is useful only when it can buy men and weaken the system from within.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Feast at Capitan Basilio’s House');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 2, 'Capitan Basilio', 'Alferez:\nA strong chain would suit me. Something worthy of my rank.\n\nCapitan Basilio:\nDo not worry, Señor Alferez. I can take care of the payment for now.', 'A chain for authority must be strong. It should remind others who commands respect.', 'I can lower the price. There is no need to burden Capitan Basilio.', 'Every chain reminds the people who holds them by the neck.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Alferez’s Watch-Chain');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 3, 'Capitan Basilio', 'Curate:\nThe earrings must be beautiful. They are for a lady.\n\nCapitan Basilio:\nOf course, Padre. Do not worry about the account.', 'For the Church, only the finest. A gift must shine brighter when it comes from important hands.', 'Would it not be better if such money were given to the poor?', 'The Church takes from the poor, then calls the payment a holy gift.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Curate’s Earrings');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 4, 'Alferez', 'A servant quietly enters and speaks to Capitan Basilio about troubles in the town: workers arrested, carabaos dying, and people becoming poorer.\n\nCapitan Basilio:\nAlways the same complaints. Prisoners, dead animals, failing harvests, rising costs.\n\nAlferez:\nPeople complain too much. Discipline is what they need.', 'Property suffers when the people below lack discipline. Fear keeps order better than pity.', 'Too much abuse will ruin even the most patient town.', 'Every blow from the Civil Guard creates another enemy for the government.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Suffering Outside');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 5, 'Curate', 'From the street, Basilio sees Simoun inside the house. He is surprised to find the jeweler doing business with the powerful people of San Diego.\n\nCapitan Basilio:\nThat student outside looks like Basilio. He has returned to San Diego for Christmas.\n\nCurate:\nThe medical student? The one connected to Capitan Tiago?', 'A useful young man, perhaps. But youth must learn to serve quietly before dreaming too highly.', 'He has suffered enough. Let him have peace tonight.', 'Suffering students become dangerous when they discover who they truly are.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Basilio Passes Outside');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (3, 6, 'Alferez', 'Capitan Basilio:\nThey say Basilio is close to becoming a doctor. He worked hard for it.\n\nCurate:\nA poor boy rising too far may forget his place.\n\nAlferez:\nAs long as he causes no trouble, let him study.', 'Let him chase his quiet future. Quiet men are easier to govern.', 'A man who rises through hardship deserves respect.', 'A quiet man with buried grief can be sharpened into a weapon.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Basilio’s Future');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 1, 'Basilio', 'In the dark forest, Simoun digs near the old grave. His blue goggles are removed. Basilio steps out from the shadows.\n\nBasilio:\nCan I help you, sir?\n\nSimoun quickly straightens and reaches for his revolver.', 'For whom do you take me?', 'You should not be here, Basilio. Leave before you regret it.', 'So, you have discovered that Simoun is not my true name.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Basilio Discovers Simoun');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 2, 'Basilio', 'Basilio:\nThirteen years ago, in this same place, you helped bury my mother. To me, you are sacred. You are someone the world believes to be dead.\n\nAn uneasy silence follows.', 'You hold a secret that can ruin me. For my safety, I should silence you forever. Yet I will let you live.', 'If you remember me, then let the past rest. I came only to mourn.', 'Yes. I am the man they failed to kill, and I have returned to destroy them all.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Secret Identity');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 3, 'Basilio', 'Basilio:\nWhy spare me, Señor Simoun? Why trust me with this secret?', 'You and I both have debts to settle with society. Your brother was murdered, your mother was driven to madness, and no one paid for it.', 'Because revenge will not heal you. Forget what happened and build a peaceful life.', 'Because I need men like you when the country begins to burn.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Simoun Tries to Recruit Basilio');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 4, 'Basilio', 'Basilio:\nI do not wish to enter politics. I only want to finish medicine, help the people, and live quietly.', 'Then keep your little dream. But when you change your mind, find me at my house in the Escolta.', 'That is noble, Basilio. Perhaps quiet service is better than revenge.', 'Then you are useless. When the weak perish, do not ask why I did not save you.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Basilio Refuses Revenge');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 5, 'Informant', 'Later, an informant reports to Simoun about Cabesang Tales’ family.\n\nInformant:\nJuli has left her home to enter service. She needs money for her father’s ransom. Cabesang Tales is still in the hands of the tulisanes.', 'Desperation teaches faster than speeches. Watch that family closely.', 'Send them money. No daughter should suffer like that.', 'Good. Their suffering will become fuel for the uprising.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Report About Juli');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (4, 6, 'Informant', 'Informant:\nOn Christmas morning, Tandang Selo tried to greet his relatives, but no words came out. Grief has made him mute.', 'A broken voice can still become a dangerous silence. Continue observing them.', 'Tell the town to comfort the old man. He has suffered enough.', 'Then give that silence a weapon, and let sorrow speak through blood.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Tandang Selo’s Silence');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 1, 'Informant', 'Informant:\nThe town speaks of Cabesang Tales’ tragedy, Señor Simoun. Yet everyone denies responsibility.\n\nInformant:\nThe Civil Guard says they only followed orders. The friar-administrator says he only protected the estate. Sister Penchang says Juli’s suffering is punishment from heaven.\n\nSimoun remains silent, listening carefully.', 'Good. When guilt is divided among many hands, no one fears punishment.', 'They should be ashamed. That family deserves justice.', 'Let them deny their guilt. One day, the oppressed will make them pay in blood.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Everyone Washes Their Hands');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 2, 'Informant', 'Informant:\nJuli now serves Sister Penchang to raise money for her father’s ransom.\n\nInformant:\nInstead of comfort, the girl is forced to work, pray, and read religious books.', 'Desperation bends people better than chains. Watch her family closely.', 'No daughter should suffer for her father’s misfortune. Help her if possible.', 'Every prayer forced upon her will become another reason for revolt.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Juli’s Servitude');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 3, 'Sister Penchang', 'Capitana Tika:\nSeñor Simoun, your jewels are truly magnificent.\n\nSister Penchang:\nI must see the diamond ring promised for the Virgin of Antipolo.\n\nCabesang Tales watches silently, surrounded by poverty while jewels shine before him.', 'Choose carefully. A jewel is not only beauty; it is power held in the palm of the hand.', 'Perhaps these jewels are too much for a house filled with sorrow.', 'One jewel could save a family, yet the rich wear them while others starve.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Jewels at Tales’ House');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 4, 'Cabesang Tales', 'Simoun fires his revolver toward a distant palm tree. Cabesang Tales sees its power.\n\nCabesang Tales:\nThe tulisanes have rifles that can reach far.', 'This revolver reaches far enough. A steady hand can make one man equal to many.', 'Weapons only bring more suffering. It is better not to touch them.', 'A weapon in the hand of the oppressed is the first true lesson in justice.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Revolver');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 5, 'Informant', 'Informant:\nCabesang Tales saw the friar-administrator and the new tenant walking through his fields.\n\nInformant:\nHe said nothing, but his face changed. The land was everything he had left.', 'A man who loses land loses fear. Let him decide what price he will pay for it.', 'He must calm himself. Anger will only destroy what remains of his family.', 'Good. Let his anger ripen. A wounded farmer can become a blade.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Tales’ Rage');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (6, 6, 'Servant', 'Servant:\nSeñor Simoun, the revolver is gone. Cabesang Tales has disappeared.\n\nServant:\nHe left Juli’s locket in its place.', 'A fair exchange. Some men pay with gold. Others pay with what remains of their heart.', 'We must report the theft at once.', 'At last. The land has given birth to another rebel.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Missing Revolver');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 1, 'Padre Sibyla', 'Ben-Zayb:\nHis Excellency came to Los Baños for rest, yet papers and petitions still follow him.\n\nPadre Camorra:\nPetitions, petitions! These students want too much.\n\nPadre Sibyla:\nEspecially this request for an academy of Castilian.', 'Students ask because they are encouraged to ask. Deny them too quickly, and they will ask louder.', 'Perhaps the students only want education. That should not frighten anyone.', 'Deny them. Let their disappointment become the spark they need.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Captain-General’s Rest');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 2, 'Padre Sibyla', 'High Official:\nThe students’ request is legal. If we reject it without reason, we only create resentment.\n\nPadre Camorra:\nEducation will make them arrogant.\n\nPadre Sibyla:\nKnowledge in the wrong hands becomes danger.', 'Then give them a school that still keeps them under control. A gift can also be a chain.', 'They should be allowed to learn freely. Ignorance weakens the country.', 'The more you fear their minds, the more powerful those minds will become against you.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Academy Debate');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 3, 'Ben-Zayb', 'Padre Irene:\nThe matter can be passed to Don Custodio. He may study it and make the proper recommendation.\n\nBen-Zayb:\nA wise solution. Don Custodio is famous for projects.', 'Excellent. Delay is often more useful than refusal.', 'Delay is unfair. The students deserve a direct answer.', 'Good. Let them taste hope first. Broken hope makes men easier to push toward violence.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Don Custodio as Arbiter');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 4, 'Padre Camorra', 'High Official:\nYour Excellency, the daughter of Cabesang Tales has come again. She begs for the release of her sick grandfather.\n\nCaptain-General:\nCan no one let me eat in peace?\n\nPadre Camorra:\nI came to support that girl’s petition.', 'Mercy costs little when it is given late. Let the order be signed if it pleases His Excellency.', 'She should have been heard sooner. The old man should never have been arrested.', 'Release him or not, the damage is done. Families remember what governments forget.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Juli’s Petition');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 5, 'Informant', 'Informant:\nA student named Placido Penitente is losing patience with the University.\n\nInformant:\nHe walks to class with anger, tired of professors, memorization, and humiliation.', 'Students tire easily. Watch him, but do not approach him yet.', 'He deserves encouragement. A hardworking student should not be crushed.', 'Good. A humiliated student is dry wood waiting for flame.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Placido’s Frustration');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (7, 6, 'Informant', 'Informant:\nPlacido walks with Juanito Pelaez, a favored student. Juanito survives through charm and tricks.\n\nInformant:\nPlacido seems disgusted by him.', 'Every system has pets and victims. The pets are useful; the victims are more interesting.', 'Placido should avoid men like Juanito if he wants to remain honorable.', 'Let Placido see the unfairness clearly. Hatred grows faster when comparison is near.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Juanito Pelaez');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 1, 'Informant', 'Informant:\nPadre Millon teaches physics, but the students learn mostly fear.\n\nInformant:\nThey memorize words like machines. Mistakes are punished with mockery.', 'A school that teaches fear is still useful. Fear prepares men to obey.', 'That is not education. That is abuse disguised as teaching.', 'Every insult in that classroom sharpens the knife against the rulers.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Physics Class Report');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 2, 'Informant', 'Informant:\nPlacido was called by Padre Millon. The professor mocked him, twisted his answers, and accused him of prompting.\n\nInformant:\nThen his absences were read aloud before the class.', 'Humiliation is a strong teacher. Some men crawl after it; others bite.', 'The professor went too far. No student should be treated like that.', 'Good. Let the University create the enemies I will need.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Placido Is Targeted');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 3, 'Informant', 'Informant:\nPlacido finally lost patience. He told the professor he had no right to insult him, then left the class.\n\nInformant:\nThe room was terrified. Such dignity is rarely seen there.', 'Then he has courage. Courage, when properly guided, can be made useful.', 'He should return and apologize before his future is destroyed.', 'He has taken the first step. Soon he may be ready to strike back.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Placido Walks Out');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 4, 'Informant', 'Informant:\nThe students gathered at Makaraig’s house. Their academy petition has reached Don Custodio.\n\nInformant:\nThey believe there is still hope.', 'Hope is useful. Let them hold it a little longer before it is taken away.', 'I hope they succeed. Their academy would help the youth.', 'When their hope fails, they will finally understand that reform is a trap.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Students Gather');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 5, 'Informant', 'Informant:\nSome students suggest using Pepay, the dancing girl close to Don Custodio.\n\nInformant:\nJuanito Pelaez says he can help through her.', 'Influence often enters through doors that honor refuses to touch.', 'They should never use shameful methods for a noble cause.', 'Let them see that even education must kneel before corruption.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Pepay’s Influence');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (8, 6, 'Informant', 'Informant:\nIsagani refuses to use Pepay first. He wants to speak with Señor Pasta through honorable means.\n\nInformant:\nThe others agreed. Isagani will visit the lawyer.', 'Let the poet try honor. It is useful for young men to discover its price.', 'Isagani is right. Honest methods should be respected.', 'The old lawyer will teach him what this country does to honest dreams.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Isagani Chooses Señor Pasta');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 1, 'Informant', 'Informant:\nIsagani visited Señor Pasta. At first, the lawyer welcomed him warmly because he knew Isagani’s uncle.\n\nInformant:\nBut when Isagani mentioned the academy, friars, the Captain-General, and Don Custodio, Señor Pasta became cautious.', 'Caution is the refuge of men who own too much to risk anything.', 'Perhaps Señor Pasta only needs time to think before helping them.', 'Educated cowards are more useful to tyranny than soldiers.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Isagani Meets Señor Pasta');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 2, 'Informant', 'Informant:\nSeñor Pasta said he loved the country and progress, but he could not compromise himself.\n\nInformant:\nHe spoke of prudence, interests, laws, and delicate positions.', 'A man who speaks too much usually means to do nothing.', 'He is afraid. We should not judge him too harshly.', 'Men like him prove why peaceful reform will never free this country.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Señor Pasta Refuses');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 3, 'Quiroga', 'Quiroga:\nSeñor Simoun, welcome. My house is full tonight. Officials, merchants, and friends all come to honor me.\n\nSimoun looks around at the guests eating, drinking, praising Quiroga, and hiding their own interests.', 'Honor? They come because your table is full and your favors may be useful.', 'You are fortunate to have so many loyal friends.', 'Greed gathers men faster than patriotism ever could.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Quiroga’s House');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 4, 'Quiroga', 'Quiroga:\nSeñor Simoun, I am ruined. The diamond bracelets were taken by a powerful lady. I cannot pay you everything.\n\nQuiroga:\nHave mercy. Reduce my debt.', 'Mercy has a price. If you cannot pay with money, you will pay with service.', 'Forget the debt. I know you did not intend to lose them.', 'You will pay by helping me arm the storm that is coming.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Quiroga’s Debt');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 5, 'Quiroga', 'Simoun lowers his voice.\n\nSimoun:\nYou have warehouses, Quiroga. You have space. You have men who ask few questions.\n\nQuiroga:\nWhat do you want from me, Señor Simoun?', 'Keep some boxes for me. Say nothing. When the time comes, you will be paid in protection.', 'Never mind. It is too dangerous. I will find another way.', 'Hide rifles and cartridges. They will be used when Manila begins to burn.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Rifles');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (9, 6, 'Simoun', 'Quiroga:\nBut if the boxes are found, I will be blamed!\n\nSimoun:\nOnly if you are foolish.\n\nQuiroga trembles.', 'If handled well, fear becomes profit. A search can ruin enemies and enrich friends.', 'You are right. This plan may hurt innocent people.', 'Let the innocent tremble. Terror will weaken the city before the revolt.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Searches and Fear');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 1, 'Padre Camorra', 'Juanito Pelaez:\nSeñor Simoun, the fair is full tonight. Everyone is speaking of Mr. Leeds and his mysterious talking head.\n\nBen-Zayb:\nA talking head? Nonsense. It must be optics, mirrors, or some American trick.\n\nPadre Camorra:\nOr the devil himself.', 'If you wish to know whether it is mirrors or devils, then see the famous sphinx yourselves.', 'Leave it alone. Such shows are useless and not worth our attention.', 'Sometimes the dead speak because the living have buried too many crimes.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Quiapo Fair');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 2, 'Padre Salvi', 'Ben-Zayb:\nI tell you, it is physics. One mirror here, another there, and the illusion is complete.\n\nPadre Camorra:\nBah! Your science cannot explain everything.\n\nPadre Salvi:\nSuch exhibitions should be watched carefully.', 'Then let us examine it. If Ben-Zayb is right, he may write about science. If the padre is right, he may forbid it.', 'Science and religion should not quarrel over a fair attraction.', 'Science, religion, and government all fear the same thing: a hidden truth becoming visible.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Ben-Zayb’s Explanation');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 3, 'Don Custodio', 'Padre Salvi:\nI do not like this. A talking head, a dark room, a foreigner, and a crowd hungry for wonders.\n\nDon Custodio:\nStill, if we go privately, no one can say we mixed with the common crowd.', 'There is nothing to fear, Padre. It is only a box, unless your conscience gives it a voice.', 'If Padre Salvi is uncomfortable, we should respect his feelings and leave.', 'Perhaps Padre Salvi fears the head will speak of Santa Clara.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Padre Salvi’s Uneasiness');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 4, 'Padre Camorra', 'Mr. Leeds:\nLadies and gentlemen, this box came from an ancient tomb. Inside it are ashes and a secret older than memory.\n\nBen-Zayb:\nThe mirrors must be hidden somewhere. I will find them.\n\nPadre Camorra:\nBegin already! This air smells like a corpse.', 'Proceed, Mr. Leeds. Curiosity has already paid the entrance fee.', 'This is disrespectful. The dead should not be used for entertainment.', 'A dead head may give truer testimony than living courts.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Inside Mr. Leeds’ Exhibit');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 5, 'Ben-Zayb', 'The Talking Head:\nI know the crimes hidden beneath robes, prayers, and silence.\n\nPadre Salvi turns pale. His hands tremble.\n\nBen-Zayb:\nImpossible. There must be mirrors!', 'An impressive illusion. Manila will gossip about this for days.', 'Padre Salvi looks unwell. The show should stop.', 'Let the guilty friar hear what the dead remember.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Talking Head Speaks');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (11, 6, 'Ben-Zayb', 'Don Custodio:\nThis exhibition must be stopped. It disturbs the peace and frightens respectable people.\n\nPadre Camorra:\nYes, forbid it. Such things belong to darkness.\n\nBen-Zayb:\nStill, I am certain it was done with mirrors.', 'Then close it. Fear is easier to control when authority gives it a name.', 'The public should be free to see it and judge for themselves.', 'No, let the fear spread. Panic weakens the Church faster than argument.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: After the Show');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 1, 'Placido Penitente', 'Placido Penitente:\nSeñor Simoun! Señor Simoun! I need to speak with you.\n\nSimoun stops near his carriage and looks at Placido through his blue goggles.\n\nPlacido Penitente:\nI want to ask a favor. I want to leave this place.', 'Why?', 'Poor boy. Tell me everything, and I will help you.', 'Your anger has finally made you useful.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Placido Calls Simoun');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 2, 'Placido Penitente', 'Placido Penitente:\nI want to go to Hong Kong. I want to live free, become rich, and fight the friars from there.\n\nSimoun watches him quietly.', 'Come with me. To Calle Iris.', 'I will write you a recommendation, then you may leave in peace.', 'Do not run to Hong Kong. Stay here and help burn the system that humiliated you.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Placido Wants Hong Kong');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 3, 'Placido Penitente', 'Placido Penitente:\nI am tired of studying. The University has become a place of insults.\n\nSimoun remains silent for a moment as the carriage moves through the city.', 'Speak little. A man who wishes to change his fate must first learn silence.', 'You have suffered enough. You should rest before making any decision.', 'The revolution needs men who have been humiliated.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Inside the Carriage');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 4, 'Informant', 'Informant:\nSeñor Simoun, Don Custodio’s decision on the students’ academy has been approved.\n\nInformant:\nThe academy is accepted in name, but it will be placed under a religious corporation or connected to the University.', 'A favorable answer that chains them is better than an open refusal.', 'That is unfair. The students deserve a school that is truly theirs.', 'Good. Broken hope creates better rebels than direct oppression.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Don Custodio’s Decision');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 5, 'Informant', 'Informant:\nThe students are angry. They say their victory is only an insult.\n\nInformant:\nThey plan to leave the theater and hold a banquet at a pansiteria.', 'Let them laugh. Mockery wastes anger better than action.', 'They have the right to protest. Their disappointment is justified.', 'Let the banquet become the first signal.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Students’ Reaction');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (12, 6, 'Informant', 'Informant:\nPlacido Penitente is still angry. He may be willing to follow you.', 'Keep him near but unsatisfied. Desperation moves faster than command.', 'Send him safely to Hong Kong. He deserves freedom.', 'Give him weapons tonight. A humiliated student should learn how revenge feels.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Placido’s Usefulness');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 1, 'Informant', 'Informant:\nSeñor Simoun, the theater is full. Everyone is asking who owns the empty box.\n\nInformant:\nA rumor has spread that it belongs to you.', 'Let them believe it. An absent man can command more attention than one seated in plain sight.', 'Correct the rumor. I want no attention tonight.', 'Good. While they stare at an empty box, I prepare the city for blood.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Empty Theater Box');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 2, 'Informant', 'Informant:\nSome say you were seen with Mr. Jouay. Others say you gave a necklace to one of the actresses.\n\nInformant:\nThe audience is whispering about you.', 'A necklace opens doors more quietly than a command.', 'It was only admiration. There is no purpose behind it.', 'The actress, the palace, and the theater are all useful pieces for tonight.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Necklace Rumor');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 3, 'Informant', 'Informant:\nInside the theater, everyone acts important. Critics pretend to understand art. Social climbers pretend to understand French.\n\nInformant:\nEven those who understand nothing speak loudly.', 'Manila loves performance. Its rulers, writers, and fools are all actors.', 'Theater should educate people and inspire virtue.', 'Let them applaud. They do not know the ground beneath them is ready to explode.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Manila Performs');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 4, 'Informant', 'Informant:\nMakaraig returned with the news. The academy is approved, but only under the control of the religious corporations or the University.\n\nInformant:\nThe students feel mocked.', 'A victory poisoned from inside. Don Custodio is not useless after all.', 'Their academy should have been independent. They worked honestly for it.', 'Excellent. Every insult is another coal for the fire.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Academy Decision Reaches the Students');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 5, 'Informant', 'Informant:\nThe students left the theater during the performance. The whole audience noticed.\n\nInformant:\nThey are going to a pansiteria to hold a sarcastic banquet.', 'Let them go. Youthful anger always seeks witnesses.', 'Stop them before they offend the authorities.', 'Follow them closely. Perhaps they are finally ready to rebel.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Students Leave');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (13, 6, 'Informant', 'Informant:\nAt the pansiteria, the students mock Don Custodio, Padre Irene, the friars, the government, and even the country’s condition.\n\nInformant:\nTheir laughter is loud, but the streets outside are listening.', 'Mockery is safe. Action is rare. Let them talk.', 'They are brave. At least they still dare to speak.', 'Words against the friars are the first gunshots.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Banquet');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 1, 'Informant', 'Informant:\nSeñor Simoun, you were seen near the convent of Santa Clara while the church bells were ringing.\n\nInformant:\nSome may wonder why you were there instead of at the theater.', 'I go where business calls. Bells, theaters, and gossip do not concern me.', 'The bells reminded me of someone I once loved.', 'Tonight those convent doors may finally break open.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Near Santa Clara');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 2, 'Basilio', 'Basilio:\nSeñor Simoun, why are you here at this hour?\n\nSimoun sees Basilio’s books and notices the pamphlets left unopened.', 'You have not opened the pamphlets I sent. You are not interested in your country.', 'I came only to ask about Capitan Tiago’s condition.', 'In less than an hour, Manila will drown in blood, and I want you beside me.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Basilio’s Room');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 3, 'Basilio', 'Basilio:\nWhat do you want from me?\n\nSimoun’s voice lowers.', 'I offer you death or a future. With us or with the government. With your country or with your oppressors.', 'You may remain neutral. I will not force you to choose.', 'Join me, or when my men enter the streets, I will let them judge you as an enemy.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Death or Future');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 4, 'Basilio', 'Basilio:\nIf I joined you, what would I have to do?', 'While the city looks elsewhere, you will lead men to Santa Clara, force open its doors, and take out the person only you and I can recognize.', 'We will ask the convent peacefully. Perhaps they will release her.', 'Burn the convent if you must. Nothing holy remains in a prison.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Mission at Santa Clara');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 5, 'Basilio', 'Basilio:\nMaria Clara is dead. She died this evening.\n\nSimoun freezes. His face turns pale.', 'It is a lie! Maria Clara lives. Maria Clara must live!', 'Then the plan has failed. We must postpone everything calmly.', 'If she is dead, then nothing remains but to destroy everyone who stole her from me.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Maria Clara Is Dead');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (14, 6, 'Informant', 'Informant:\nThe next day, Isagani met Paulita at the Malecon.\n\nInformant:\nHe spoke of a future Philippines with railroads, factories, ships, liberty, and dignity. Paulita called them dreams.', 'Dreamers build clouds. Disappointed men build history.', 'Perhaps his dream is better than mine.', 'Let Isagani dream. Soon my fire will decide the future for him.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Isagani’s Dream');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 1, 'Informant', 'Informant:\nSeñor Simoun, the students gathered at the pansiteria after the theater.\n\nInformant:\nThey were laughing, but their laughter was bitter. They mocked the decision about the academy.', 'Let them laugh. Laughter wastes anger better than action.', 'They laugh because they were treated unjustly.', 'Good. Their laughter is the sound of anger waiting to become revolt.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The Students’ Banquet');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 2, 'Informant', 'Informant:\nThey dedicated dishes to Don Custodio, Padre Irene, the friars, and the government.\n\nInformant:\nTheir jokes were sharp enough to offend anyone who heard them.', 'Mockery is harmless until someone teaches it to hold a weapon.', 'At least they still have courage to speak.', 'Those jokes can become the first slogans of a rising people.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Mocking the Powerful');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 3, 'Informant', 'Informant:\nA man watched them carefully, then left the pansiteria.\n\nInformant:\nThe students noticed him. Some believe their words have already been reported.', 'Good. Loose tongues are useful when someone is listening.', 'Spying on students is unnecessary. They are only disappointed youths.', 'Every name reported tonight can help push them closer to rebellion.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Spy');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 4, 'Informant', 'Informant:\nThis morning, seditious pasquinades were found on the doors of the University.\n\nInformant:\nPeople say the students are involved. Rumors of arrests are spreading.', 'Let suspicion spread. Fear makes the city easier to move.', 'The guilty should be found first. The innocent must not be blamed.', 'Those papers are only the beginning. Soon the walls themselves will speak.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Pasquinades');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 5, 'Informant', 'Informant:\nSome students are denying their connection to the association. Juanito Pelaez is distancing himself.\n\nInformant:\nBut Isagani argues that where there is danger, there is honor.', 'Fear separates cowards from useful men.', 'Isagani has honor. Men like him should be protected.', 'The brave ones will be the first to light the fire.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Fear Among the Students');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (16, 6, 'Informant', 'Informant:\nBasilio went to Makaraig’s house to borrow money, but guards were already there.\n\nInformant:\nMakaraig was arrested, and Basilio was taken too.', 'I warned Basilio. Authority always needs victims.', 'Basilio is innocent. He should not suffer for this.', 'Let prison finish what grief began. Basilio will come to me changed.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Basilio Is Arrested');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 1, 'Informant', 'Informant:\nPadre Fernandez called Isagani for a private conversation.\n\nInformant:\nHe heard Isagani speaking boldly and wanted to understand the students.', 'Let them talk. Words often make men feel brave while changing nothing.', 'Perhaps one friar may still understand justice.', 'If even a friar listens now, then the old wall is beginning to crack.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Padre Fernandez Calls Isagani');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 2, 'Informant', 'Informant:\nIsagani told Padre Fernandez that the students want freedom in education.\n\nInformant:\nHe said the friars should not oppose the emancipation of teaching.', 'They ask for what power cannot safely give.', 'The request is fair. Education should not be feared.', 'Once they learn freely, they will finally see the chains around them.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: What the Students Want');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 3, 'Informant', 'Informant:\nIsagani said students often leave school with their dignity torn apart.\n\nInformant:\nPadre Fernandez was disturbed by his words.', 'Dignity is expensive. Most men sell it cheaply.', 'The professors should treat students with respect.', 'Humiliation is the best teacher for future rebels.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Student Dignity');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 4, 'Informant', 'Informant:\nThe pasquinades have frightened the city. People whisper of arrests, deportations, and rebellion.\n\nInformant:\nSome say the students are connected with tulisanes. Others speak of foreign ships and secret plots.', 'Fear travels faster than truth. Let it travel.', 'This panic will hurt innocent people.', 'Good. A frightened city is easier to break.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Panic in Manila');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 5, 'Informant', 'Informant:\nQuiroga is frightened. The hidden rifles may be discovered if the authorities search houses.\n\nInformant:\nHe wonders whether he can still profit from the confusion.', 'Fear and profit are old partners. Tell him to keep his mouth closed.', 'He should get rid of the rifles before he is caught.', 'Tell him those rifles will soon have their purpose.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Quiroga’s Fear');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (17, 6, 'Informant', 'Informant:\nPadre Irene told Capitan Tiago about the arrests and rumors.\n\nInformant:\nThe old man became terrified. His condition worsened.', 'Fear kills more quietly than poison.', 'Poor Capitan Tiago. He should not have been frightened like that.', 'Let the old world die of its own terror.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Capitan Tiago’s Fear');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 1, 'Informant', 'Informant:\nCapitan Tiago is dead. His funeral is grand.\n\nInformant:\nBecause he left wealth to the Church and religious causes, people speak kindly of his soul.', 'In Manila, even salvation seems easier for those who leave enough money behind.', 'Death should be honored sincerely, not bought with donations.', 'Gold buys heaven for the rich while the poor are buried with curses.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Capitan Tiago’s Funeral');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 2, 'Informant', 'Informant:\nWith Capitan Tiago dead, Basilio has lost his strongest protector.\n\nInformant:\nHe remains in prison while the others hope their families can save them.', 'A man without a patron is easy prey for authority.', 'Someone should protect Basilio. He does not deserve this.', 'Good. When all protection disappears, vengeance becomes easier to accept.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Basilio Without Protection');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 3, 'Informant', 'Informant:\nJuli heard that Basilio is imprisoned. She fainted when the news reached her.\n\nInformant:\nShe believes she must save him, because he once saved her.', 'Love can drive people where orders cannot.', 'She must be kept away from danger.', 'If Basilio’s suffering breaks her, then her suffering will break him.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: Juli Hears the News');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 4, 'Informant', 'Informant:\nThe people say only Padre Camorra can help Basilio.\n\nInformant:\nBut Juli fears going to him. She knows what kind of man he is.', 'Power always sells favors at a price.', 'No woman should be forced to ask help from such a man.', 'Let the village see what hides behind holy robes.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Padre Camorra’s Influence');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 5, 'Informant', 'Informant:\nJuli went to the convento. What happened inside is not spoken clearly.\n\nInformant:\nBut afterward, she fell from the window and died.', 'Tragedy teaches what sermons hide.', 'This should never have happened.', 'Her death will become a wound Basilio cannot ignore.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Juli’s Death');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (18, 6, 'Informant', 'Informant:\nTandang Selo has lost almost everything: his land, his son, his granddaughter, and his voice.\n\nInformant:\nNow he has disappeared.', 'Some grief does not speak. It walks into the mountains.', 'Find him and bring him comfort.', 'Give that silence a weapon, and sorrow will learn to answer.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Tandang Selo’s Silence');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 1, 'Informant', 'Informant:\nThe high official tried to defend Basilio before the Captain-General.\n\nInformant:\nHe said Basilio is a medical student with good reports from his teachers.', 'Let him speak. Mercy often loses when authority needs an example.', 'The high official is right. Basilio should be freed.', 'When justice fails openly, rebellion gains another reason to exist.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: The High Official Defends Basilio');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 2, 'Informant', 'Informant:\nThe Captain-General refused to release Basilio.\n\nInformant:\nHe said someone must remain punished so the authority of the government will not look weak.', 'An example is more useful to rulers than the truth.', 'An innocent man should never be used as an example.', 'Every innocent prisoner is a future recruit.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Someone Must Be Punished');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 3, 'Informant', 'Informant:\nThe high official became disgusted. He argued that a government without justice creates its own enemies.\n\nInformant:\nThen he chose to leave and return to Spain.', 'One honest official leaving changes nothing.', 'Men like him are needed here.', 'When honest men abandon the government, the government is ready to fall.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The High Official Resigns');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 4, 'Informant', 'Informant:\nThe students’ futures are ruined. Some are suspended. Some families pull their sons out of school.\n\nInformant:\nMakaraig escaped, others were released, but Basilio remains in prison.', 'One prisoner is enough to keep fear alive.', 'Basilio has suffered enough. He should be released.', 'Keep him there until he hates everything he once hoped for.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Effects of the Pasquinades');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 5, 'Informant', 'Informant:\nYou have recovered from illness, Señor Simoun. Don Timoteo Pelaez is preparing a grand wedding for Juanito and Paulita.\n\nInformant:\nThe most powerful people in Manila may attend.', 'Tell Don Timoteo the celebration must be grand. Important guests deserve a spectacle.', 'After all these troubles, it is better to avoid attention.', 'Gather them in one house, and one flame can finish them.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Simoun Recovers');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (19, 6, 'Informant', 'Informant:\nPaulita Gomez will marry Juanito Pelaez.\n\nInformant:\nIsagani has been abandoned. Juanito is safer, richer, and more acceptable to society.', 'Society rewards safety, not poetry.', 'She should have followed her heart.', 'A broken lover may still become useful when the night of fire arrives.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Paulita Chooses Juanito');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 1, 'Basilio', 'Basilio:\nSeñor Simoun, I was wrong before. I refused you, and now everything I loved has been taken from me.\n\nBasilio:\nGive me a weapon. Let the revolution come. I am ready to serve.', 'At last, grief has opened your eyes. I knew suffering would teach what words could not.', 'No, Basilio. Revenge will only destroy you. Go back and live peacefully.', 'Good. I need men broken enough to kill without hesitation.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Basilio Returns');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 2, 'Basilio', 'Basilio:\nYou were right. Peaceful dreams are useless in this country.\n\nBasilio:\nWhat do you want me to do?', 'You came at the right hour. My hesitation is gone. Tonight, force will answer force.', 'Perhaps there is still time to seek justice through lawful means.', 'Tonight, Manila will learn that Ibarra has returned to punish them.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Simoun’s Doubt Ends');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 3, 'Basilio', 'Simoun reveals an elegant lamp shaped like a pomegranate.\n\nBasilio:\nWhat is that?', 'A wedding gift. Beautiful enough for the powerful, and deadly enough for justice.', 'It is only a lamp. Nothing more.', 'It is a bomb filled with nitroglycerin, made to kill every tyrant gathered tonight.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Pomegranate Lamp');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 4, 'Basilio', 'Basilio:\nWhere will it be placed?', 'At the wedding feast. When the light weakens and someone raises the wick, the house will become a tomb.', 'I will place it somewhere empty, only to frighten them.', 'The dining room is mined with powder. Not one guest, servant, friar, or official will escape.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: The Plan');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 5, 'Basilio', 'Basilio:\nIf the lamp can do everything, why do you still need me?', 'When the explosion begins, you will move among the people. Use the confusion. Help turn terror into uprising.', 'You are right. I do not need you. Leave before you are involved.', 'You will lead the first killings while the city is blind with smoke.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Basilio’s Role');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (21, 6, 'Don Timoteo Pelaez', 'Don Timoteo Pelaez:\nSeñor Simoun, everything must be perfect. The Captain-General himself will attend as sponsor.\n\nDon Timoteo Pelaez:\nMy son Juanito will marry Paulita Gomez, and Manila will remember this feast.', 'Then make it grand. The greater the guests, the greater the honor of my gift.', 'Keep the celebration simple. Too much attention is dangerous.', 'Gather them all. One house, one flame, one final judgment.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Wedding Preparation');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 1, 'Servant', 'Servant:\nSeñor Simoun, the guests are arriving. The Captain-General, friars, officials, and wealthy families are inside.\n\nServant:\nEveryone is admiring the decorations.', 'Good. Let them admire the house before it becomes their monument.', 'There are too many people. Perhaps this should stop.', 'Every important enemy is here. Tonight, they die together.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Entering the Feast');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 2, 'Ben-Zayb', 'Guest:\nSeñor Simoun, what a beautiful lamp! Is this your wedding gift?\n\nBen-Zayb:\nA marvelous novelty! Surely something foreign and scientific.', 'A small gift. Its light is enough to honor the finest table in Manila.', 'Careful. It is fragile and should not be touched by anyone.', 'Admire it well. It will be the last light many of you will ever see.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Presenting the Lamp');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 3, 'Guest', 'Guest:\nA strange message has appeared: “Mene, Tekel, Phares.”\n\nPadre Salvi turns pale.\n\nGuest:\nAnd it is signed with the name Juan Crisostomo Ibarra.', 'A tasteless joke, perhaps. A dead name still frightens the living.', 'That name should not be mocked. Some memories deserve respect.', 'Dead men return when justice has waited too long.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Message');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 4, 'Servant', 'Servant:\nSeñor Simoun, will you not stay for the dinner?\n\nServant:\nThe guests are expecting you.', 'I must fetch another wedding gift. Tell them I will return.', 'I cannot remain. I feel uneasy tonight.', 'I have already given them what they deserve. I only need distance now.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Leaving the House');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 5, 'Informant', 'Basilio, outside the house, sees Isagani staring at the balcony where Paulita appears with Juanito.\n\nBasilio:\nIsagani, leave this place! The house is mined. The lamp is death.\n\nIsagani:\nPaulita is inside.\n\nBasilio runs away in fear. Isagani turns toward the house.\n\nInformant:\nSeñor Simoun, Basilio has warned Isagani. The young man may interfere.', 'A broken lover hesitates. He will think of himself before he thinks of others.', 'Stop him. No innocent man should be allowed to die for this.', 'If he touches that lamp, kill him before he reaches the river.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Basilio Sees Isagani');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (22, 6, 'Informant', 'Informant:\nSeñor Simoun, the lamp did not explode.\n\nInformant:\nSomeone rushed inside, seized it, ran away, and threw it into the river.\n\nInformant:\nThe guests are alive. Rumors are spreading. The Civil Guard may search for you.', 'Then the night has failed. Burn every trace. We disappear before fear learns my name.', 'Thank God. Perhaps this failure saved us from becoming monsters.', 'Find the thief. Find Isagani. I will not let one fool steal my revenge.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Lamp Is Gone');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 1, 'Informant', 'Informant:\nSeñor Simoun, the city is full of rumors. They found sacks of powder hidden in Don Timoteo’s house.\n\nInformant:\nPeople say the whole street could have been destroyed if the lamp had exploded.', 'Rumors grow larger when people are afraid. Let them confuse themselves.', 'They should know the truth. Isagani saved them from death.', 'If the lamp had burned, all of them would now be ashes.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Rumors After the Failed Explosion');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 2, 'Informant', 'Informant:\nSome now whisper your name. They say only you and Don Timoteo knew the house well enough.\n\nInformant:\nOthers say you are the devil because of your jewels, strange house, and blue flames.', 'Fear needs a face. If they call me devil, they still do not know the whole truth.', 'I should explain myself before the rumors destroy me.', 'Devil or man, I nearly sent their rulers to judgment.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: Simoun Is Named');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 3, 'Informant', 'Informant:\nThe Civil Guard is searching for you. Your name spreads from house to house.\n\nInformant:\nIf they find you, they may not wait for trial.', 'Burn every trace. Use no names. Gold still buys silence if spent quickly.', 'Perhaps I should surrender and defend myself.', 'If they catch me, I will drag every coward who helped me into the fire.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Civil Guard Searches');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 4, 'Informant', 'Informant:\nPeople still do not know who stole the lamp and threw it into the river.\n\nInformant:\nSome suspect a Spaniard, others a Chinese man, and others a Filipino. Isagani hears the rumors but says nothing.', 'A silent man is useful. Let him carry the secret and suffer under it.', 'He did what I could not. He saved the innocent.', 'Find Isagani. He stole my revenge, and he must pay for it.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Isagani’s Silence');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 5, 'Informant', 'Informant:\nIn the provinces, Matanglawin has become the terror of Luzon.\n\nInformant:\nMany believe he is Cabesang Tales, the farmer who lost his land, his family, and his old life.', 'A man robbed of land can become a name that frightens landlords.', 'Cabesang Tales should have been saved before grief turned him into that.', 'The mountains now carry the rebellion I wanted Manila to begin.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: Matanglawin in the Mountains');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (26, 6, 'Informant', 'Informant:\nThe Civil Guards fought the tulisanes in the mountains. Among them was Tano, the son of Cabesang Tales.\n\nInformant:\nHe fired at a figure on the rocks. Later, he saw the dying man and recognized him. It was his grandfather, Tandang Selo.', 'That is the harvest of injustice. Remember it, but speak of it to no one.', 'God forgive us. That family has suffered beyond measure.', 'The boy has fired on his own blood. Now let the whole country burn.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: Tano and Tandang Selo');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 1, 'Padre Florentino', 'Wounded and exhausted, Simoun arrives at Padre Florentino’s house by the sea.\n\nPadre Florentino:\nYou came here wounded and alone. The Civil Guard may be searching for you.\n\nPadre Florentino:\nWhat do you ask of me?', 'Only a corner, Padre, and silence until the night passes.', 'Save me, Padre. I am afraid of death.', 'Hide me, or the government will learn how much blood I meant to spill.', 1, 0, 0, 10, -10, 10, 35, 'Scene 1: Padre Florentino’s House');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 2, 'Padre Florentino', 'Padre Florentino:\nA message came. The authorities are looking for a wounded Spaniard hidden in this house.\n\nPadre Florentino:\nAre you the man they seek?', 'They seek many things, Padre. A man, a name, a shadow, a crime.', 'Yes. I failed, and now I have nowhere else to run.', 'Yes. My bomb failed, my enemies live, and I came here to die.', 1, 0, 0, 10, -10, 10, 35, 'Scene 2: The Fugitive');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 3, 'Padre Florentino', 'Padre Florentino:\nThen speak plainly. Who are you truly, and why did you return to this country?', 'I returned seeking justice, but I fed my soul with revenge until justice and hatred wore the same face.', 'I am only a jeweler who was trapped by politics.', 'I am Ibarra, the dead man they failed to bury, and I returned to destroy them all.', 1, 0, 0, 10, -10, 10, 35, 'Scene 3: The Confession');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 4, 'Padre Florentino', 'Padre Florentino:\nFreedom cannot be born from hatred alone. A people forced into violence without understanding will only fail.\n\nPadre Florentino:\nA sacrifice must be pure if it is to save the country.', 'Then why was justice denied until hatred was the only thing left alive in me?', 'You are right. I should have forgiven everything from the beginning.', 'If I had another lamp, Padre, I would still burn them all.', 1, 0, 0, 10, -10, 10, 35, 'Scene 4: Padre Florentino’s Judgment');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 5, 'Padre Florentino', 'Padre Florentino:\nThe country was not ready for the revolution you planned.\n\nPadre Florentino:\nIf the people rise through fraud and force, without knowing what they fight for, even victory becomes another failure.', 'I wanted to awaken them with thunder because whispers had failed.', 'Then let the people sleep forever. They deserve their chains.', 'A people does not need understanding. It needs blood, fear, and command.', 1, 0, 0, 10, -10, 10, 35, 'Scene 5: The Failed Revolution');
INSERT INTO quest_dialogues (quest_id, sequence_order, npc_name, npc_text, option_a_text, option_b_text, option_c_text, option_a_correct, option_b_correct, option_c_correct, suspicion_penalty, option_a_delta, option_b_delta, option_c_delta, context_notes) VALUES (31, 6, 'Padre Florentino', 'Padre Florentino:\nWhat of your jewels, Simoun? This treasure has bought silence, corruption, and death.\n\nSimoun’s breathing weakens. The sea roars outside.', 'Then let it sink where greed cannot reach it. Let the future decide if it deserves to rise again.', 'Use it for masses, churches, and prayers for my soul.', 'Keep it for the next war. Let another man finish my revenge.', 1, 0, 0, 10, -10, 10, 35, 'Scene 6: The Treasure');
